def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the full separator line.
    row_line = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    col_line = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    # The most common non-separator color is the background.
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != 2 and grid[r][c] != bg]
    if not cells:
        return out

    if row_line is not None:
        rows = [r for r, c in cells]
        if max(rows) < row_line:
            dr = row_line - 1 - max(rows)
            marker_row = min(rows) + dr - 1
        else:
            dr = row_line + 1 - min(rows)
            marker_row = max(rows) + dr + 1

        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        if 0 <= marker_row < h:
            out[marker_row] = [8] * w

    elif col_line is not None:
        cols = [c for r, c in cells]
        if max(cols) < col_line:
            dc = col_line - 1 - max(cols)
            marker_col = min(cols) + dc - 1
        else:
            dc = col_line + 1 - min(cols)
            marker_col = max(cols) + dc + 1

        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nc = c + dc
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        if 0 <= marker_col < w:
            for r in range(h):
                out[r][marker_col] = 8

    return out
